import sys,json,shutil,time
import numpy as np
from scipy import sparse
from skfem import MeshTet,Basis,ElementVector,ElementTetP1,asm
from skfem.models.elasticity import linear_elasticity,lame_parameters
from baseline_registry import ROOT,REPO,ref,dump
from primary_corotated_support import Support

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated/primaryP1_finite_increment2/summary.json';s=json.loads(src.read_text());a=dict(np.load(REPO/s['source_field']['path']));p=np.load(REPO/s['predictor_npz']['path']);trial=np.load(REPO/s['trial_field_npz']['path']);loads=json.loads((REPO/s['trial_loads_json']['path']).read_text());local=json.loads((REPO/s['source']['path']).read_text());field=np.load(REPO/local['output']['path']);model=Support(a,local['elastic_bodies']);u=a['u_mm'];N=len(u);Kparts=[]
 for name in local['elastic_bodies']:
  X=a[name+'_points_mm'];o=int(a[name+'_offset']);current=X+u[o:o+3*len(X)].reshape(-1,3);t=a[name+'_tetra'];mesh=MeshTet(current.T,t.T);el=ElementVector(ElementTetP1());lam,mu=lame_parameters(float(a[name+'_E_MPa']),float(a[name+'_nu']));K=sparse.csr_matrix((3*len(X),3*len(X)))
  # Independent chunk size; same declared currentgeometry linear metric.
  for first in range(0,len(t),10000):K+=asm(linear_elasticity(lam,mu),Basis(mesh,el,intorder=2,elements=np.arange(first,min(first+10000,len(t)))))
  Kparts.append(K)
 K=sparse.block_diag(Kparts+[sparse.csr_matrix((6,6))],format='csc');K=sparse.triu(K,format='csc')+sparse.triu(K,1,format='csc').T;ks=a['bolt_k_N_mm'];B=sparse.csr_matrix(np.vstack([model.connectors(u,np.eye(14)[j])[1] for j in range(14)]));Q=sparse.csr_matrix(a['gauge_Q']);geo=json.loads((ROOT/'validation/integrated/primaryP1_surface_geometry3/summary.json').read_text());g=np.load(REPO/geo['output']['path']);J=sparse.csr_matrix((g['J_data'],g['J_indices'],g['J_indptr']),shape=tuple(g['J_shape']));ext,_=model.connectors(u);du=p['increment_mm'];tt=p['linearized_bolt_force_N']/ks;y=p['QP_dual'];nc=2169;nq=Q.shape[0];yc=y[:nc];yq=y[nc:nc+nq];yb=y[nc+nq:nc+nq+14];yt=y[nc+nq+14:];gradient=field['elastic_force_N']-p['source_applied_force_N'];stationarity=K@du+gradient+J.T@yc+Q.T@yq-B.T@yb;tstation=ks*tt+yb+yt;linear_gap=p['source_gaps_mm']+J@du;gauge=Q@(u+du)-a['gauge_targets_mm'];branch=tt-ext-B@du;primal=max(float(np.max(np.maximum(-linear_gap,0))),float(np.max(abs(gauge))),float(np.max(np.maximum(-branch,0))),float(np.max(np.maximum(-tt,0))));dual=max(float(np.max(abs(stationarity))),float(np.max(abs(tstation))));component_norms={}
 for name in local['elastic_bodies']:
  o=int(a[name+'_offset']);n=3*len(a[name+'_points_mm']);component_norms[name]=dict(max_N=float(np.max(abs(stationarity[o:o+n]))),norm_N=float(np.linalg.norm(stationarity[o:o+n])))
 component_norms['Motor']=dict(max_N=float(np.max(abs(stationarity[model.mo:]))),norm_N=float(np.linalg.norm(stationarity[model.mo:])));dy=np.array([0,loads['root_freeY_increment_mm']*.001,0]);expected_defect=np.cross(dy,np.array(loads['upstream']['Root_origin_wrench_N_Nm'][:3]));observed=np.array(s['trial']['current_residual_wrench_N_Nm'][3:]);moment_error=observed-expected_defect;pressure=trial['pressure_N'];actualres=trial['actual_elastic_force_N']-trial['actual_contact_pullback_N']+trial['actual_bolt_pullback_N']-trial['applied_force_N'];res_error=float(np.max(abs(actualres-trial['actual_stationarity_N'])));complementarity=float(np.max(abs(linear_gap*(-yc))));checks=dict(primal_report_reproduced=abs(primal-s['QP']['prim_res'])<1e-8,dual_report_reproduced=abs(dual-s['QP']['dual_res'])<1e-8,actual_residual_reproduced=res_error<1e-8,freeY_physical_moment_defect=np.linalg.norm(moment_error)<1e-10,QP_rejection_confirmed=primal>1e-8 and dual>1e-8,nonlinear_rejection_confirmed=float(np.max(abs(actualres)))>1e-8 and trial['actual_gaps_mm'].min()<-1e-8)
 np.savez_compressed(out/'residuals.npz',QP_stationarity_N=stationarity,QP_t_stationarity_N=tstation,linearized_gap_mm=linear_gap,gauge_residual_mm=gauge,branch_residual_mm=branch)
 result=dict(status='ACTUAL_P1_ONE_INCREMENT_FAILURE_INDEPENDENTLY_CONFIRMED' if all(checks.values()) else 'ACTUAL_P1_ONE_INCREMENT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),source_field=s['source_field'],verifier=ref(out/'verifier.py'),output=ref(out/'residuals.npz'),checks={k:bool(v) for k,v in checks.items()},QP_primal_residual=primal,QP_dual_residual=dual,QP_linear_complementarity_Nmm=complementarity,QP_residual_by_body=component_norms,maximum_gauge_residual_mm=float(np.max(abs(gauge))),maximum_branch_violation_mm=float(np.max(np.maximum(-branch,0))),actual_residual_reconstruction_error_N=res_error,physical_missing_freeY_moment_Nm=expected_defect.tolist(),observed_current_residual_moment_Nm=observed.tolist(),missing_freeY_moment_error_Nm=moment_error.tolist(),root_freeY_remaining_increment_mm=loads['root_freeY_increment_mm'],no_new_solver_run=True,no_new_contact_update=True,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start,limitations=['Independent currentmetric chunkassembly andexactsavedQPcoefficients/dualorientation reproduceactual2400iterationFAIL; no extraphysicsupdate/polish/retry. CurrentisotropicSPDmetric is not constitutiveJacobian.','Currentmomentdefect is the explicitreturnedRootfreeYoffset forcecouple, not reason to subtract torque atBase. Fullcoupledclosure mustresolve freeY andall2169contacts/14branches; all22gatesremainunqualified.'])
 dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if all(checks.values()) else 2)
if __name__=='__main__':main()
